// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a concrete scenario: first deploy, then call SetMinSum(10)
        c.SetMinSum(10);
        // Call Initialized to finalize setup (reference blocks further SetMinSum, mutant doesn't care)
        c.Initialized();
        // Now try to set MinSum again: reference will revert because intitalized is true
        // But we can still check the stored MinSum after the fact.
        // Instead, we use a different path: call Collect(1) which reads MinSum.
        // First send some ETH to the contract so Collect can succeed
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.Put{value: 1 ether}(0); // sets balance = 1 ether, unlockTime = block.timestamp
        vm.warp(block.timestamp + 1); // advance time so unlockTime passes
        // Now try Collect(1) – this should succeed in reference because MinSum==10 and balance>=10? No, balance is 1e18 (1 ether) so balance >= MinSum (10), balance >= _am (1), time past unlock.
        // The reference MinSum is 10, the buggy MinSum is 0 (since buggy SetMinSum was called after Initialized? Actually the buggy version has no guard, so SetMinSum(10) always works and sets to 10. But the difference is: after Initialized, calling SetMinSum again: reference reverts so MinSum stays at 0 (default), buggy sets to 10. So we need to call SetMinSum again after Initialized.
        // Let's reorder: deploy, Initialized first, then SetMinSum(10): reference reverts, buggy sets to 10.
        // To catch the revert we need try/catch. Let me restructure.
        // Actually simpler: deploy, Initialized, then try SetMinSum(10): reference reverts, buggy does not. Then collect and check MinSum.
        // But the problem statement says the difference is observed after Collect(...) completes: P.MinSum() != M.MinSum(). So we can trigger a scenario where Collect succeeds and then read MinSum.
        // Let me deploy a fresh contract and follow the sequence: 
        // 1. Deploy
        // 2. Call SetMinSum(10) – works both
        // 3. Call Initialized – works both
        // 4. Call SetMinSum(5) – reference reverts (so MinSum stays 10), buggy sets to 5
        // But we need after Collect to see difference. Let's just call SetMinSum again after Initialized using try/catch to see if it succeeds.
        // But easier: just assert the revert behavior.
        // Let's do:
        bool ok;
        try c.SetMinSum(5) { ok = true; } catch { ok = false; }
        // Reference will revert (so ok=false), buggy will not revert (ok=true).
        // But the problem wants the difference to be observable via Collect and MinSum value.
        // The simplest: after Initialized, call SetMinSum(10) again via try. In reference, it reverts, so MinSum stays 0 (default). In buggy, it succeeds, MinSum=10. Then call Collect(1) – but it will succeed only if balance >= MinSum. Let's fund.
        // This is complex. Let me just pick: after deploy, Initialized, then try SetMinSum(10). In reference, it reverts, so MinSum remains 0. In buggy, it succeeds, MinSum becomes 10. Then send 1 wei and call Put(0) to add balance, then warp past unlock, then call Collect(1): reference Collect reverts because balance (1) < MinSum (0)? Actually MinSum=0 so balance>=MinSum holds. But the buggy MinSum=10 so balance=1 < 10 => reverts. So Collect succeeds in reference but reverts in buggy? That's a revert difference. Let's check: reference MinSum=0, balance=1, _am=1, time>unlock => Collect succeeds and sends 1 wei. Buggy MinSum=10, balance=1 < 10 => Collect reverts. So we can catch that.
        // OK:
        vm.deal(address(this), 1);
        vm.prank(address(this));
        c.Put{value: 1}(0);
        vm.warp(block.timestamp + 1);
        // Now try Collect(1):
        bool collectOk;
        try c.Collect(1) { collectOk = true; } catch { collectOk = false; }
        assertTrue(collectOk, "Collect should succeed in reference");
    }
}

