pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 10 initially
        c.SetMinSum(10);
        // Initialize the contract (finalizes MinSum in reference)
        c.Initialized();
        // Try to change MinSum again — in reference this reverts (because initialized), in mutant it succeeds
        // So we catch the revert here, but actually we need to test later behavior.
        // Instead, do the second SetMinSum and then call Collect to observe the difference.
        // The difference: reference MinSum remains 10, mutant MinSum becomes 20.

        // Fund an account with Ether
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        // Put 1 ether with lock time 0 (so unlock time = block.timestamp)
        c.Put{value: 1 ether}(0);

        // Now warp forward so unlock time is passed (block.timestamp > 0, so it's fine)
        vm.warp(block.timestamp + 1);

        // Now try to change MinSum again after initialization (this is the key step)
        c.SetMinSum(20);

        // Now call Collect with amount 10 (wei). In reference, MinSum = 10, balance = 1e18 >= 10, balance >= 10, unlock passed -> should succeed.
        // But wait, the assertion is about MinSum state after Collect, not about revert.
        // Actually the difference from the prompt: after Collect completes, P.MinSum() != M.MinSum().
        // So we just call Collect (which may revert or not), then check MinSum.
        vm.prank(user);
        c.Collect(10);

        // Check MinSum: in reference it should be 10 (since second SetMinSum reverted), in mutant it's 20
        uint minSum = c.MinSum();
        assertTrue(minSum == 10, "MinSum should be 10 in reference, but test fails on buggy version");
    }
}

