pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: fund the contract and two users
        vm.deal(address(0x1), 10 ether);
        vm.deal(address(0x2), 10 ether);

        // Call SetMinSum(10) by address(0x1) – allowed before initialization
        vm.prank(address(0x1));
        c.SetMinSum(10);

        // Initialize the contract
        vm.prank(address(0x1));
        c.Initialized();

        // Now try SetMinSum(20) – should be blocked in reference but not in buggy
        vm.prank(address(0x1));
        c.SetMinSum(20);

        // Prepare for Collect: deposit 10 ether for address(0x2) with lockTime=0 (unlock on deposit)
        vm.prank(address(0x2));
        c.Put{value: 10 ether}(0);

        // Warp past unlockTime
        vm.warp(block.timestamp + 100);

        // Now try Collect(5 ether) – reference succeeds (MinSum=10, balance=10, 10>=10), buggy reverts (MinSum=20, 10>=20 false)
        vm.prank(address(0x2));
        bool ok;
        try c.Collect(5 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: MinSum=10, so require(acc.balance>=MinSum) passes (10>=10), ok=true
        // Buggy: MinSum=20, so require(acc.balance>=MinSum) fails (10>=20 false), ok=false
        assertTrue(ok);
    }
}

