pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a valid log address (a dummy address)
        address logAddr = address(0x1234);
        c.SetLogFile(logAddr);
        // Initialize the contract
        c.Initialized();
        // Now set a small MinSum so Collect can succeed if log works
        c.SetMinSum(1 ether);
        // Give the test contract some ether and call Put to create a balance
        vm.deal(address(this), 10 ether);
        c.Put{value: 10 ether}(0); // unlockTime = block.timestamp
        // Warp past unlockTime
        vm.warp(block.timestamp + 1 days);
        // Try to call Collect(1 ether) — in the reference, this should revert because
        // SetLogFile cannot be called after init (but it was called before) — wait, the reference allows SetLogFile before init.
        // Actually the issue: after init, SetLogFile is called again? The bug allows it, the reference reverts.
        // But in the reference we called it before init, so the log address is set.
        // To diverge, we need to call SetLogFile after init and see if Collect succeeds.
        // Let's reset: start fresh.
        c = new C();
        // First initialize
        c.Initialized();
        // Then try to set log file — reference reverts, bug does not.
        // For the test, we need to see the effect on Collect. So we set a dummy log file first.
        // Actually simpler: directly after init, try to change log and then Collect.
        // But if reference reverts in SetLogFile, the state of LogFile remains unchanged (still zero address).
        // If bug accepts, LogFile becomes a valid address. Then Collect's internal call to LogFile.AddMessage will revert if LogFile=address(0)? No, it will call into zero address and succeed vacuously? Actually sending a call to address(0) returns success.
        // So both may succeed. Need a different approach: have LogFile be a contract that reverts if called twice?
        // The reference forbids changing log after init; the bug allows it.
        // We can deploy a malicious Log contract that tracks if it's called and fails if called more than once.
        // But the test only allows one contract (C). So we need to check a state difference.
        // The difference stated: after Collect, P.SetLogFile() != M.SetLogFile(). That means the log address changes.
        // The reference SetLogFile reverts, so LogFile stays at previous value; bug SetLogFile changes it.
        // But Collect does not change SetLogFile. Wait: the difference is that the log address itself differs.
        // So after a sequence: init, set log to addr1, then try to set log to addr2 (revert vs succeed), then Collect.
        // The reference will have LogFile = addr1; bug will have LogFile = addr2.
        // But we can't read LogFile because it's not public? Actually LogFile is a public state variable, so we can read c.LogFile().
        // So the test: call SetLogFile(addr1), init, then call SetLogFile(addr2) — reference reverts so LogFile stays addr1, bug succeeds so LogFile becomes addr2.
        // Then call Collect — but Collect might not differ. The assertion: c.LogFile() returns different values.
        // But the problem asks to drive through Collect. So we must call Collect last and then assert on something that Collect changes.
        // Collect changes acc.balance and emits a log. But the log is internal.
        // The only observable after Collect: balance, unlockTime, maybe LogFile itself.
        // Actually Collect does not change LogFile. So the divergence must be that in the bug, Collect succeeds (because LogFile is callable), in reference it reverts? No.
        // Let's re-read: the bug is that SetLogFile can be called after init. The reference reverts. How does that affect Collect? Collect calls LogFile.AddMessage. If LogFile is address(0), the call succeeds (no code executes). If LogFile is a contract that reverts on second call? Not needed.
        // The problem statement says: "after a call to Collect(...) completes, the value of state variable SetLogFile differs". That is impossible because Collect does not change SetLogFile. Perhaps they mean the log address (the variable named LogFile) differs.
        // So the test: call SetLogFile(addr1), init, call SetLogFile(addr2) — reference reverts so LogFile stays addr1, bug succeeds so LogFile = addr2.
        // Then call Collect. After that, read c.LogFile() and assert it equals addr1 for reference, addr2 for bug.
        // But that's not driven through Collect. The problem says "Driven through the public/external entry Collect".
        // Maybe the intent: the act of calling Collect reveals the state difference. For instance, if LogFile is a contract that on AddMessage modifies some state, then after Collect the state would differ. But we can't deploy another contract.
        // Another possibility: Collect's success depends on LogFile being set correctly? No.
        // Let's just make the assertion on c.LogFile() after the whole sequence, because that's the direct difference.
        // The test must pass on reference and fail on bug. We'll use c.LogFile().
        address addr1 = address(0x1111);
        address addr2 = address(0x2222);
        c.SetLogFile(addr1);
        c.Initialized();
        // Try to change log; reference will revert, so we wrap in try-catch
        bool success;
        try c.SetLogFile(addr2) {
            success = true;
        } catch {
            success = false;
        }
        // If success, bug has addr2; if fail, reference has addr1.
        // But to make assertion after Collect, we must call Collect.
        // Set MinSum and provide ether.
        c.SetMinSum(1 ether);
        vm.deal(address(this), 10 ether);
        c.Put{value: 10 ether}(0);
        vm.warp(block.timestamp + 1 days);
        c.Collect(1 ether);
        // Now assert: in reference, LogFile is addr1; in bug, LogFile is addr2.
        assertTrue(c.LogFile() == addr1);
    }
}

