        // We'll deploy a simple Log contract.
        Log logContract = new Log();
        c.SetLogFile(address(logContract));
        c.Initialized();
        // Now Put
        vm.prank(user);
        c.Put{value: 1}(0);
        // warp past unlockTime
        vm.warp(1);
        // Now user tries to collect 2
        vm.prank(user);
        bool ok;
        try c.Collect(2) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, Collect should revert (balance < _am), so ok=false.
        // In mutant, Collect should succeed (no revert), so ok=true.
